<?php
define('ML_APP',true);define('ML_ROOT',__DIR__.'/..');require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Version.php';require_once __DIR__.'/../core/Config.php';use Core\Config;$args=array_slice(isset($argv)?$argv:array(),1);$quiet=false;$help=false;$dryRun=false;$single='';foreach($args as $a){$a=(string)$a;if($a==='--quiet'||$a==='-q'){$quiet=true;}elseif($a==='--help'||$a==='-h'){$help=true;}elseif($a==='--dry-run'||$a==='--dry'){$dryRun=true;}elseif(strpos($a,'--task=')===0){$single=substr($a,7);}}if($help){echo"媒资资料库 · 统一计划任务入口（v".ML_APP_VERSION."）\n\n";echo"用法： php cron/run.php [--quiet] [--dry-run] [--task=KEY] [--help]\n\n";echo"每条任务槽：\n";echo"  hourly         增量采集（每 ~55 分钟）\n";echo"  trending       每日热门 + 全量静态（每天 03:30）\n";echo"  refresh        过期刷新 + 全量静态（每天 05:00）\n";echo"  link_check     链接失效检测（每天 04:30）\n";echo"  api_logs_prune API 流水清理（每天 06:00）\n";echo"  rate_prune     限流/缓存/分区清理（每天 03:00）\n";echo"  pan_transfer   批量补转存（每天 04:00，v5.2.1 起默认开启）\n";echo"  match_auto     全自动网盘匹配（每 5 分钟，有候选才跑）\n";echo"  pan_match      消费网盘待匹配队列（仅队列非空时）\n\n";echo"  —— 可选槽（默认关闭，需后台 app_settings.cron.<键名>=1 开启；\n";echo"    手动补跑不受开关限制）：\n";echo"    build_static  全量重建静态页（每天 02:00，键 cron.build_static_enabled）\n";echo"                   预热缓存/修复漏网页面用；热门与过期刷新末尾已各自全量重建，\n";echo"                   日常不配也能跑\n\n";echo"示例：\n";echo"  php cron/run.php --quiet\n";echo"  php cron/run.php --dry-run\n";echo"  php cron/run.php --task=link_check\n";echo"  php cron/run.php --task=build_static   （手动补跑一次全量重建，不受开关限制）\n";exit(0);}$lockFile=ML_ROOT.'/config/cron_run.lock';$lockFp=@fopen($lockFile,'c');if(!$lockFp||!@flock($lockFp,LOCK_EX|LOCK_NB)){fwrite(STDERR,"cron_run: 已有实例在运行（lock=".$lockFile."），本次退出。\n");exit(0);}$stateFile=ML_ROOT.'/config/cron_run.state.json';$state=array();if(is_file($stateFile)){$dec=@json_decode(@file_get_contents($stateFile),true);if(is_array($dec)){$state=$dec;}}function cron_php_binary(){if(defined('PHP_BINARY')&&(string)PHP_BINARY!==''){return(string)PHP_BINARY;}$a=getenv('PHP_BINARY');if($a!==false&&$a!==''){return $a;}return'php';}function cron_flag_on(array $a,$b){if(!isset($a[$b])){return true;}$c=$a[$b];return!($c==='0'||$c===0||$c===false||$c==='false');}function cron_flag_off(array $a,$b){if(!isset($a[$b])){return false;}$c=$a[$b];return($c==='1'||$c===1||$c===true||$c==='true');}function cron_hourly_ready(array $a,$b,$c){if(!isset($a[$b]['ts'])){return true;}return(time()-(int)$a[$b]['ts'])>=$c;}function cron_daily_ready(array $a,$b,$c,$d){$e=time();$f=((int)date('H',$e))*60+(int)date('i',$e);$g=$c*60+$d;if($f<$g){return false;}if(!empty($a[$b]['ok'])&&date('Y-m-d',(int)$a[$b]['ts'])===date('Y-m-d',$e)){return false;}return true;}function cron_run_slot($a,$b,array&$c,$d,$e,$f){$g=cron_php_binary();$h=preg_split('/\s+/',trim((string)$b),-1,PREG_SPLIT_NO_EMPTY);$i=array_shift($h);$j=__DIR__.'/'.$i;$k=$g.' -d opcache.enable_cli=0 '.escapeshellarg($j);foreach($h as $l){$k.=' '.escapeshellarg($l);}if($e){echo"[dry] 将执行 ($a): $k\n";return 0;}if(!$d){echo"---- [$a] ".date('Y-m-d H:i:s')." ----\n";}$m=0;passthru($k,$m);$c[$a]=array('ts'=>time(),'ok'=>($m===0),'code'=>(int)$m,);return $m;}$slots=array('hourly'=>array('script'=>'sync_hourly.php --quiet','type'=>'hourly','min'=>3300,),'rate_prune'=>array('script'=>'rate_prune.php','type'=>'daily','h'=>3,'m'=>0,),'trending'=>array('script'=>'sync_trending.php --quiet','type'=>'daily','h'=>3,'m'=>30,),'link_check'=>array('script'=>'link_check.php --quiet --limit=40','type'=>'daily','h'=>4,'m'=>30,),'refresh'=>array('script'=>'sync_refresh.php --quiet','type'=>'daily','h'=>5,'m'=>0,),'api_logs_prune'=>array('script'=>'api_logs_prune.php --days=90 --quiet','type'=>'daily','h'=>6,'m'=>0,),'build_static'=>array('script'=>'build_static.php --quiet','type'=>'daily','h'=>2,'m'=>0,'opt'=>'build_static_enabled',),'pan_transfer'=>array('script'=>'pan_transfer.php --limit=20','type'=>'daily','h'=>4,'m'=>0,),);$anyFail=false;if(!defined('ML_MATCH_AUTO_LIMIT')){$cronCfg0=Config::get('cron',array());$maLimit=20;if(isset($cronCfg0['match_auto_limit'])){$maLimit=max(1,min(50,(int)$cronCfg0['match_auto_limit']));}define('ML_MATCH_AUTO_LIMIT',$maLimit);}if($single!==''){$known=array_keys($slots);$known[]='pan_match';if(!in_array($single,$known,true)){fwrite(STDERR,"未知任务槽：--task=$single（可选：".implode('/',$known)."）\n");@flock($lockFp,LOCK_UN);@fclose($lockFp);exit(1);}if($single==='pan_match'){$code=cron_run_pan_match($state,$quiet,$dryRun);$anyFail=($code!==0);}elseif($single==='match_auto'){$code=cron_run_slot('match_auto','pan_match_auto.php --quiet --limit='.ML_MATCH_AUTO_LIMIT,$state,$quiet,$dryRun,true);$anyFail=($code!==0);}else{$code=cron_run_slot($single,$slots[$single]['script'],$state,$quiet,$dryRun,true);$anyFail=($code!==0);}}else{foreach($slots as $key=>$def){$ready=false;if($def['type']==='hourly'){$ready=cron_hourly_ready($state,$key,$def['min']);}else{$ready=cron_daily_ready($state,$key,$def['h'],$def['m']);}if(!$ready){if(!$quiet&&!$dryRun){echo"[skip] $key（时间槽未到 / 今日已跑）\n";}continue;}if($key==='rate_prune'){$cronCfg=Config::get('cron',array());$rpEnabled=true;if(isset($cronCfg['rate_prune_enabled'])){$v=$cronCfg['rate_prune_enabled'];if($v==='0'||$v===0||$v===false||$v==='false'){$rpEnabled=false;}}if(!$rpEnabled){if(!$quiet){echo"[skip] rate_prune（后台配置已关闭：cron.rate_prune_enabled=0）\n";}$state[$key]=array('ts'=>time(),'ok'=>true,'code'=>0,'disabled'=>true);continue;}}if(isset($def['opt'])){$cronCfgO=Config::get('cron',array());if(!cron_flag_off($cronCfgO,$def['opt'])){if(!$quiet&&!$dryRun){echo"[skip] $key（可选槽未开启：cron.".$def['opt']." 未设为 1）\n";}$state[$key]=array('ts'=>time(),'ok'=>true,'code'=>0,'disabled'=>true);continue;}}$code=cron_run_slot($key,$def['script'],$state,$quiet,$dryRun,false);if($code!==0){$anyFail=true;}}$code=cron_run_pan_match($state,$quiet,$dryRun);if($code!==0){$anyFail=true;}$cronCfg2=Config::get('cron',array());$maEnabled=true;if(isset($cronCfg2['match_auto_enabled'])){$v=$cronCfg2['match_auto_enabled'];if($v==='0'||$v===0||$v===false||$v==='false'){$maEnabled=false;}}if(!$maEnabled){if(!$quiet&&!$dryRun){echo"[skip] match_auto（后台配置已关闭：cron.match_auto_enabled=0）\n";}$state['match_auto']=array('ts'=>time(),'ok'=>true,'code'=>0,'disabled'=>true);}else{$code=cron_run_slot('match_auto','pan_match_auto.php --quiet --limit='.ML_MATCH_AUTO_LIMIT,$state,$quiet,$dryRun,false);if($code!==0){$anyFail=true;}}}if(!$dryRun){$tmp=$stateFile.'.tmp';if(@file_put_contents($tmp,json_encode($state,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT))!==false){@rename($tmp,$stateFile);}}@flock($lockFp,LOCK_UN);@fclose($lockFp);if(!$quiet&&!$dryRun){echo"==== cron 统一入口结束 ".date('Y-m-d H:i:s')." ====\n";}exit($anyFail?1:0);function cron_run_pan_match(array&$a,$b,$c){$d=ML_ROOT.'/config/pan_pending.txt';if(!is_file($d)||trim((string)@file_get_contents($d))===''){if(!$b&&!$c){echo"[skip] pan_match（无待处理队列）\n";}return 0;}return cron_run_slot('pan_match','pan_match_delayed.php --from-pending --delay=0',$a,$b,$c,false);}